List<List<Integer>> result = new ArrayList<>();

public void backtrack(int[] nums, List<Integer> path, int startIndex) {
    // 结束条件：收集结果
    result.add(new ArrayList<>(path)); // 注意要拷贝

    // 遍历选择列表
    for (int i = startIndex; i < nums.length; i++) {
        // 剪枝：跳过不合法的选择
        if (shouldSkip(nums, i, startIndex)) continue;

        // 做选择
        path.add(nums[i]);

        // 递归进入下一层
        backtrack(nums, path, i + 1); // 或 i（子集问题可重复选）

        // 撤销选择（回溯）
        path.remove(path.size() - 1);
    }
}
